import 'dart:convert';import 'package:flutter_test/flutter_test.dart';import 'package:http/http.dart' as http;import 'package:http/testing.dart';import 'package:fenleng_sdk_flutter/fenleng_sdk_flutter.dart';
void main(){test('stale entitlement cannot authorize',()async{final client=FenlengFlutterClient(options:FenlengClientOptions(baseUrl:'http://localhost',storage:FenlengMemoryStorageAdapter(),httpClient:MockClient((_)async=>http.Response(jsonEncode({'items':[{'entitlements':{'pro':true}}]}),200))));final sdk=FlutterEntitlementSDK(client:client,applicationId:'app',maxAge:Duration.zero);await sdk.refresh();await Future<void>.delayed(const Duration(milliseconds:1));expect(sdk.has('pro'),false);});test('feedback attachment requires consent',(){final client=FenlengFlutterClient(options:FenlengClientOptions(baseUrl:'http://localhost',storage:FenlengMemoryStorageAdapter(),httpClient:MockClient((_)async=>http.Response('{}',200))));final sdk=FlutterFeedbackSDK(client:client,projectId:'app',version:'1');expect(()=>sdk.submit('broken','idempotent-key',screenshot:'data'),throwsA(isA<FenlengSdkException>()));});}
